  { pattern: /\b(?:ARBs?|angiotensin (?:II |2 )?receptor blockers?)\b/i, member: /\b(?:losartan|valsartan|olmesartan|candesartan|irbesartan|telmisartan|azilsartan|eprosartan)\b/i },
