      ["hdl", /\bHDL(?:[ -]cholesterol)?\b/i], ["ldl", /\bLDL(?:[ -]cholesterol)?\b/i],
      ["cholesterol", /^(?:total cholesterol|cholesterol(?:,? total)?)$/i], ["triglycerides", /^triglycerides?$/i],
    ];
